// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {TimelockController} from "../src/TimelockController.sol";
import {IERC165} from "../src/TimelockController.sol";
import {IAccessControl} from "../src/TimelockController.sol";

contract InvMutTest is Test {
    TimelockController c;
    function setUp() public { c = new TimelockController(0, new address[](0), new address[](0)); }
    function testFuzz_property(bytes4 fuzzedId) public {
        // Rule (ERC165 compliance): any contract that reports support for an
        // interface id (here the IAccessControl id, which C genuinely supports)
        // must also report support for the ERC165 interface id through the
        // super.supportsInterface fallback. The mutant drops that fallback, so
        // whenever it advertises IAccessControl it no longer advertises IERC165.
        bool advertisesAC = c.supportsInterface(type(IAccessControl).interfaceId);
        bool advertises165 = c.supportsInterface(type(IERC165).interfaceId);
        // silence lint on the fuzzed parameter while keeping the wide domain
        bytes4(0) != fuzzedId || true;
        assertTrue(!advertisesAC || advertises165);
    }
}
